#include <stddef.h>
#include <stdint.h>
int64_t nagel_schrekenberg(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<5||v[0]<2||v[0]>32||v[1]<0||v[1]>16||v[2]<0||v[2]>5||n!=(size_t)v[0]+3)return -1;size_t cells=(size_t)v[0],steps=(size_t)v[1];int row[32],next[32],moved[32];for(size_t i=0;i<cells;i++){if(v[i+3]< -1||v[i+3]>5)return -1;row[i]=(int)v[i+3];}size_t need=cells*(steps+1);if(need>cap||(need&&!out))return -2;size_t p=0;for(size_t j=0;j<cells;j++)out[p++]=(uint8_t)(row[j]+1);for(size_t t=0;t<steps;t++){for(size_t i=0;i<cells;i++){next[i]=-1;if(row[i]!=-1){size_t d=0,j=i+1;for(;j<cells;j++){if(row[j]!=-1)break;d++;}if(j==cells)for(j=0;j<cells;j++){if(row[j]!=-1)break;d++;}int speed=row[i]+1;if(speed>v[2])speed=(int)v[2];if(speed>(int)d-1)speed=(int)d-1;next[i]=speed;}}for(size_t j=0;j<cells;j++)moved[j]=-1;for(size_t i=0;i<cells;i++)if(next[i]!=-1)moved[(i+(size_t)next[i])%cells]=next[i];for(size_t j=0;j<cells;j++){row[j]=moved[j];out[p++]=(uint8_t)(row[j]+1);}}return (int64_t)p;}
